// help.js - Help: topics with search (the Help tab), and the "?" buttons that
// open the topic for the page in view.
//
// A "?" is <a class="helpq" data-help="prefix">: its topic is
// `prefix-<data-p of the selected tab next to it>` (e.g. settings-storage,
// admin-users, camera-recording), else `prefix` itself. Or give data-topic.

import { esc, openDlg } from './core.js';

const k = (x) => '<kbd>' + x + '</kbd>';

// [id, section, title, extra search words, html]
const TOPICS = [
  // ---------------------------------------------------------------- basics
  ['start', 'Basics', 'Getting around', 'tabs header menu account theme phone bottom bar more',
    '<p>On a computer the tabs across the top are <b>Live</b> (all cameras now, and playback), <b>Events</b> (what happened, as a list or a grid of clips), <b>Time-lapse</b>, <b>Settings</b> (administrators) and <b>Help</b> (this page). On a phone they are in a bar at the bottom: <b>Live</b>, <b>Events</b>, <b>Settings</b> and <b>More</b> (Time-lapse, Help, Keyboard shortcuts). A number on Events counts the events since you last opened it.</p>' +
    '<p>In the header: the <b>Armed / Disarmed</b> button turns motion detection on or off for every camera at once; a colored dot shows the state of the server, and a chip appears when something needs attention (click it to see what). The sun/moon button picks the theme; the keyboard button lists keyboard shortcuts. The account button (the <b>...</b> menu on a phone) holds theme (Auto follows your device, or Light, Dark), alert pop-ups, text size, start page, change password and sign out.</p>' +
    '<p>Press ' + k('Ctrl') + ' ' + k('K') + ' to search for a page, a setting, a camera or an action by name.</p>'],
  ['getting-started', 'Basics', 'Getting started', 'setup new install checklist first steps',
    '<p>A short checklist for a new install: add cameras, choose where recordings go, add a sign-in account, use HTTPS, get alerts on your phone and turn on AI. Each step is ticked off by looking at the real setup. Admins see a reminder on Live only while a new install still has no cameras or no sign-in account.</p>' +
    '<p class="adminonly"><a href="#" data-gs>Open the checklist</a></p>'],
  ['arming', 'Basics', 'Armed and Disarmed', 'arm disarm detection off on away home delay undo',
    '<p>The button in the header (and ' + k('S') + ') switches motion detection for every camera at once. <b>Armed</b> (green): cameras look for motion, record events and send alerts. <b>Disarmed</b> (red): no motion detection and no new events, but continuous recordings carry on. Arming can wait a few seconds so you can leave (<b>Arming in 30 s</b>; tap again to cancel). After disarming a message offers <b>Undo</b> for a few seconds.</p>' +
    '<p>Profiles and schedules (Settings &rsaquo; Schedules &amp; presence) can arm and disarm by themselves, for example when everyone leaves.</p>'],
  ['share-clip', 'Basics', 'Save or share a clip', 'download export send share video clip snapshot picture zip',
    '<p>Open an event in <b>Events</b>: its clip plays, and the buttons under it <b>download</b> it. Tick several events (the box on each row) to download them together as a ZIP. On Live, the camera buttons <b>save a snapshot</b> and <b>record a clip now</b> (20 seconds); in playback, mark an in and out point and press ' + k('E') + ' to export exactly that stretch. Protected events are never deleted automatically.</p>'],
  ['away-from-home', 'Basics', 'Watch from away from home', 'remote outside internet vpn tailscale phone travel access port forward',
    '<p>The simplest and safest way is a private network app such as Tailscale on the server and on your phone: then the same address works everywhere and nothing is opened to the internet. Turn on HTTPS (Settings &rsaquo; Users &amp; security &rsaquo; HTTPS) so the sign-in and the video are encrypted, and add a password (Settings &rsaquo; Users &amp; security &rsaquo; Users) before you reach it from outside. Alerts reach your phone anywhere once set up in Settings &rsaquo; Detection &amp; alerts &rsaquo; Alerts.</p>'],
  ['shortcuts', 'Basics', 'Keyboard shortcuts', 'keys keyboard',
    '<p>Press ' + k('?') + ' for the full list. The most used: ' + k('1') + '-' + k('9') + ' open a camera full size, ' + k('F') + ' full screen, ' + k('M') + ' mute, ' + k('P') + ' snapshot, ' + k('C') + ' record a clip now, ' + k('S') + ' arm / disarm, ' + k('T') + ' timeline mode, ' + k('V') + ' change the layout, ' + k('/') + ' search events, ' + k('Ctrl') + k('K') + ' search everything, ' + k('G') + ' then ' + k('E') + ' (or ' + k('L') + k('S') + k('H') + ') go to a page, ' + k('Esc') + ' close. In the timeline: ' + k('Space') + '/' + k('K') + ' play, ' + k('J') + k('L') + ' reverse/faster, ' + k('I') + k('O') + ' mark, ' + k('E') + ' export, ' + k('End') + ' live.</p>'],
  ['menu', 'Basics', 'Account menu', 'alert pop-ups keep screen awake sleep text size larger font data saver phone mobile cellular start page password trust certificate sign out',
    '<p><b>Theme</b>: Auto follows this device (light by day, dark by night if your device does), or choose Light or Dark. <b>Alert pop-ups</b>: show a pop-up in this browser when an alert happens. <b>Keep screen awake</b>: while AmberSight is open and showing, this computer\'s screen stays on and it does not go to sleep (per device; the browser releases it when the page is hidden or minimized). <b>Start page</b>: what opens when you sign in. <b>Text size</b>: Normal, Large or Larger, for all text on this device. <b>Data saver</b>: Auto (on when the device says the connection is slow or metered), On or Off; with it on, full-size live view uses the smaller sub stream and playback the sub stream\'s recordings where there are some (Settings &rsaquo; Recording &rsaquo; Drives &amp; folders can keep a copy for every camera). <b>Notifications on this device</b>: camera alerts pop up on this phone or computer like any app\'s notifications, even with AmberSight closed (no other app needed); it also lists your other devices and sends a test. iPhone and iPad: add AmberSight to the Home Screen first (iOS 16.4 or newer). <b>Change password</b>: at least 8 characters. <b>Trust this server</b>: install this server\'s own certificate on this device once, so the browser stops warning about HTTPS. <b>Sign out</b>.</p>'],

  // ---------------------------------------------------------------- watching
  ['live', 'Watching', 'Live view', 'grid tiles fit focus layout arrange group full screen zoom snapshot clip side panel',
    '<p>Every camera as a tile, playing its smaller sub stream. The buttons above the grid pick a view style: <b>Grid</b> (equal tiles, scroll for more), <b>Fit</b> (all cameras in the window), <b>Focus</b> and <b>Focus 2</b> (one or two cameras large). <b>Arrange</b> lets you drag tiles into order; <b>Layouts</b> saves named sets of cameras, tiles per page and order, kept with your account. The group menu shows only one group.</p>' +
    '<p>Click a tile to select it (the side panel follows it); double-click or ' + k('Enter') + ' opens it full size with the main stream and sound (tap Unmute). Full size: arrow keys or swipe for the next camera, the mouse wheel or pinch zooms, drag to pan.</p>' +
    '<p>Each tile\'s buttons: snapshot, play back this camera, its clips, record a 20 s clip now, and more (right-click works too). The badges show online/offline, the record mode (REC, REC motion, REC sub+events) and MOTION while something moves.</p>'],
  ['side-panel', 'Watching', 'Side panel: PTZ, talk, profile', 'ptz pan tilt zoom preset talk speaker intercom profile dock',
    '<p>The panel at the side (open it with the button at the left of the Live toolbar) follows the selected camera. For a PTZ camera: hold the arrows (or the arrow keys) to move it, zoom, go to presets, or click a spot to center it / drag a box to zoom there. For a camera with a speaker: hold to talk. It also shows the active profile and the server\'s status.</p>'],
  ['live-timeline', 'Watching', 'Playback on the Live page (timeline mode)', 'playback scrub rewind speed alerts strip history L',
    '<p>' + k('L') + ' (or the timeline button) turns the Live page into playback: a strip under the cameras shows what was recorded and the alerts. Click a moment to play every visible camera from exactly there, or press and drag along the strip to scrub (a picture of the moment shows above the pointer); drag the time ruler along the top, scroll sideways or use two fingers to move the strip, and scroll or pinch to zoom; ' + k('Space') + ' plays and pauses, ' + k('[') + ' ' + k(']') + ' change the speed (fast speeds show one picture per few seconds), ' + k(',') + ' ' + k('.') + ' jump to the previous or next alert, ' + k('←') + ' ' + k('→') + ' step 10 s (Shift: 60 s). Hover over the strip (or drag the playhead) for a picture of that moment. Press ' + k('L') + ' again for live. The calendar button next to Go to opens a month: days with recordings are tinted and days with alerts have a dot (for the cameras shown); click a day to go to the same time of day there, or type an exact time in the Go to field.</p>' +
    '<p>Cameras that record their sub stream between events play in full quality around events and in the lower sub-stream quality the rest of the time; playback switches between them by itself.</p>'],
  ['events', 'Watching', 'Events', 'search motion alerts objects person car protect export zip today unseen new badge list grid',
    '<p>Everything the cameras noticed, newest first. Filter by camera, what was detected (person, vehicle, animal, package...) or time (1h, Today, 24h, 7d, Custom). Open an event to play its clip, see what AI found, download it, or <b>keep it forever</b> so retention and a full drive never delete it. Tick events to download several as a ZIP. The number on the Events tab counts events since you last looked.</p>' +
    '<p><b>Grid view</b>: the list/grid control at the top of Events shows the same events as pictures, with the same filters and player. There is no separate Clips tab; old Clips links open the grid.</p>'],
  ['timelapse', 'Watching', 'Time-lapse', 'timelapse day fast summary nightly',
    '<p>A whole day of one camera in a minute or so: one picture every so many seconds, played at 30 per second. Pick the camera and the day. When turned on (admins: the settings at the bottom of the tab), yesterday\'s is made each night for every recording camera or the ones chosen; <b>Make now</b> makes any day\'s, today\'s covering the day so far. They are kept for the days set (30 by default).</p>'],
  ['servers-switch', 'Watching', 'Other servers and split view', 'linked server site cabin switch split',
    '<p>When servers are linked (Settings &rsaquo; Connections &rsaquo; Servers), the name next to the logo becomes a menu that opens another server, already signed in as the same user. Their cameras can also appear in your Live view (live only; their recordings stay there). <b>Split</b> on the Live toolbar shows two servers side by side.</p>'],

  // ---------------------------------------------------------------- settings
  ['settings-cameras', 'Settings', 'Cameras', 'add camera remove copy settings list',
    '<p>All cameras. <b>Add by address</b> asks for the stream address (RTSP or HTTP), a local device (webcam, capture card), this computer\'s screen, or a screen sent from another computer. Settings &rsaquo; Cameras &rsaquo; Find cameras finds cameras on the network for you. Click a camera to change it; <b>Copy to...</b> copies its motion, recording, alert or AI settings to other cameras. Cameras save as you change them.</p>'],
  ['camera-general', 'Camera settings', 'Camera: General', 'name short name groups enabled',
    '<p><b>Name</b> and a <b>short name</b> for places where space is tight; <b>groups</b> it belongs to (several are fine); <b>Enabled</b>: a disabled camera is not connected, recorded or shown.</p>'],
  ['camera-stream', 'Camera settings', 'Camera: Stream', 'url rtsp sub stream main username password ingest ffmpeg hardware decoding fps analysis',
    '<p>The <b>main stream</b> address is what gets recorded and shown full size. An optional <b>sub stream</b> (lower resolution) is used for motion detection and the Live grid, which saves a lot of CPU; most cameras have one (Reolink: h264Preview_01_sub). User name and password are the camera\'s own.</p>' +
    '<p>AmberSight reads RTSP cameras itself; one it cannot play after a few tries is switched to ffmpeg automatically (a camera that is merely off or rebooting is not). The analysis frame rate and width set how much CPU motion detection uses.</p>'],
  ['camera-recording', 'Camera settings', 'Camera: Recording', 'record mode continuous motion only sub stream around events pre-roll post-roll direct battery on demand space',
    '<p><b>Record mode</b>:</p><ul>' +
    '<li><b>continuous</b>: the main stream all the time.</li>' +
    '<li><b>continuous: sub stream, main stream around events</b>: the sub stream all the time and the full-quality main stream only around events, including the pre-roll (kept in memory). Uses far less space: often a tenth. Playback shows full quality wherever it was recorded. Needs a sub stream; without one the camera records continuously.</li>' +
    '<li><b>motion only</b>: nothing between events.</li></ul>' +
    '<p><b>Pre-roll</b> and <b>post-roll</b> are the seconds kept before an event starts and after it ends (blank = the default in Settings &rsaquo; Detection &amp; alerts &rsaquo; Motion sensitivity). <b>Battery camera</b>: connect only when someone watches, an event happens or the camera reports activity, then disconnect after the idle time.</p>'],
  ['camera-motion', 'Camera settings', 'Camera: Motion', 'motion detection zones ignore sensitivity object size contrast travel arm window schedule break time false alarms',
    '<p>Values left blank use Settings &rsaquo; Detection &amp; alerts &rsaquo; Motion sensitivity. <b>Arm window</b> limits detection to certain hours (e.g. 20:00-07:00). To cut false alarms: raise <b>min object size</b> (small things), <b>contrast</b> (shadows, noise) or <b>min travel</b> (swaying branches), or draw zones.</p>' +
    '<p><b>Zones</b>: on the Live page, open a camera\'s menu and choose Draw a motion zone (or use Edit zones in its settings). Motion only counts inside a detect zone, and never inside an ignore zone. Nothing is saved until you press Save. <b>Event break time</b>: how long without motion before an event ends.</p>'],
  ['camera-alert-zones', 'Camera settings', 'Camera: Alert zones (loitering and line crossing)', 'named zones area line loitering crossing tripwire direction arrow gate driveway person stays',
    '<p>In <b>Edit zones</b>, pick <b>Alert area</b> or <b>Alert line</b>, draw on the picture and name it. AI object checks must be on (Settings &rsaquo; Detection &amp; alerts &rsaquo; Objects); the zones work on what the AI sees, and the object\'s feet (the bottom center of its box) decide where it is.</p>' +
    '<p><b>Area</b>: alerts when an object of the chosen kinds stays inside longer than the time you set (loitering), once per visit. <b>Line</b>: alerts when an object\'s feet cross it. The arrow shows which way is <b>in</b> (the right-hand side walking from A to B); choose In, Out or Both. A small distance past the line is needed, so a wobbling box at the line does not count.</p>' +
    '<p><b>Ignore parked vehicles</b> (on by default): a car or truck that has sat in the same place for a few minutes does not count, so a parked car does not alert on every motion. It uses the AI setting \'Ignore objects that have not moved\', which must be on for the camera.</p><p>Each zone has its own <b>objects</b>, <b>Send alerts</b>, <b>Save events</b> (with a clip) and an optional time window. Events are tagged like <i>loitering: Driveway</i> or <i>crossed: Gate (in)</i>: search for them in Events, and they appear in alerts, MQTT (a sensor per area, an event per line in Home Assistant) and the camera\'s zone topic. Alerts follow the arm state and profiles like other alerts, and are not held back by the alert interval.</p>' +
    '<p><b>Cost</b>: while there is motion (and while someone still stands in an area, for a while), AmberSight looks at the picture about every 0.7 seconds to follow people and cars. Settings &rsaquo; Detection &amp; alerts &rsaquo; Objects has the look interval and how long to keep watching someone who stands still. Slower looks cost less but follow fast movers badly; a look is never started while the previous one is still running.</p>'],
  ['camera-trigger', 'Camera settings', 'Camera: Trigger', 'also trigger other cameras group camera detection onvif reolink',
    '<p><b>Also trigger</b>: when this camera detects motion, the cameras or groups ticked here record an event too, each with its own pre- and post-roll. A camera that was only triggered does not pass it on. A camera can also start events from its own detection (person, vehicle, doorbell press) when it reports them.</p>'],
  ['camera-alerts', 'Camera settings', 'Camera: Alerts', 'notifications channels hours interval priority quiet',
    '<p>Whether this camera sends notifications, to which services (all by default), during which hours, at most how often, and at which priority. Off still records events and reports them over MQTT; it just sends nothing. The services themselves are set up in Settings &rsaquo; Detection &amp; alerts &rsaquo; Alerts.</p>'],
  ['camera-watchdog', 'Camera settings', 'Camera: Watchdog', 'watchdog reboot restart frozen offline power cycle smart plug shelly tasmota poe switch',
    '<p>When the camera has had no video for a while (Settings &rsaquo; Connections &rsaquo; Watchdog), AmberSight restarts it through its own interface: ONVIF, or the Reolink, Dahua/Amcrest or Hikvision way (<b>Automatic</b> picks by what the camera is). It signs in with the stream user and password. If the video is still gone 5 minutes later, or the camera does not answer at all, it turns the <b>power switch</b> off and on again (a Shelly or Tasmota plug, or any switch with an off and an on address, such as a PoE switch port). If that does not help either, you get a message to check it by hand.</p>' +
    '<p><b>Test power cycle</b> tries the switch now (the camera goes offline for a minute or two). <b>Reboot camera...</b> in the camera\'s menu restarts it now. Every restart and power cycle is listed under Recent actions and in Settings &rsaquo; System &rsaquo; Audit.</p>'],
  ['settings-watchdog', 'Settings', 'Camera watchdog', 'watchdog reboot restart offline frozen power cycle quiet hours limit',
    '<p>Turns the camera watchdog on for every camera (each camera can be turned on or off on its own, Watchdog tab). <b>Act after</b>: minutes without video before it does anything. <b>At most per day</b>: restarts and power cycles per camera in 24 hours. <b>Quiet hours</b>: no restarts then (the offline alert still goes out).</p>' +
    '<p>It never acts in the first 5 minutes after AmberSight starts, starts a new round at most once an hour per camera, and does nothing while most cameras are offline at once (that is the network or the power, not the cameras). While it works on a camera, the usual offline alert waits; if it cannot fix it, the alert says so.</p>'],
  ['camera-ai', 'Camera settings', 'Camera: AI', 'object detection person car dog confidence parked labels confirm strict stricter false alerts remembered spots same spot bush shrub bin not a person camera own detection agree',
    '<p>With AI on, a motion event alerts only when AI sees one of the <b>objects that count</b> (e.g. person, car, dog) with at least the <b>minimum confidence</b>; other events are still recorded, just quiet. <b>Ignore objects that have not moved</b>: a parked car does not confirm every event; one arriving or leaving does. <b>Stricter confirmation</b>: the object must be seen in 2 of 3 looks in a row and have moved between them (fewer false alerts; someone passing very quickly may be missed). Blank values use Settings &rsaquo; Detection &amp; alerts &rsaquo; Objects (AI).</p>' +
    '<p><b>Remembered spots</b> (with Ignore objects that have not moved on): when AI sees the same kind of thing in the same spot in 3 separate events within a day (a bush or a bin it takes for a person, a car parked across the street), that spot stops alerting. For a person- or animal-shaped one it also has to have been seen there in two other events only with low confidence, which a real person seldom is; a person-shaped thing bigger than a small, far-off box is never held. Anything that moves there, or is clearly bigger or smaller, still alerts, and so does everything elsewhere in the picture. A remembered spot lasts a day, then has to be learned again; a spot not seen for a day is forgotten. A car in a remembered spot is held only if the spot was last seen with a car in it when the event began; if it was last seen empty, the car is an arrival and alerts. When something else in the picture confirms an event, AI stops looking, so a parked car may drive off unseen: the next car in that spot then alerts once. A second car on a parked car\'s spot (one driving past in front of it) alerts. The event is still recorded, labeled and searchable; its AI review says \u201chas been in that spot in several earlier events\u201d. The camera\'s AI settings show how many spots it remembers, next to the AI on/off and the objects, with <b>Forget remembered spots</b> (it asks first and acts at once, not when you press Save).</p>' +
    '<p><b>Not a person</b> (or <b>Not a car</b> ...) under the AI verdict of an event AI got wrong marks it not a real alert and remembers the spot of what sat still in it, at once, for 30 days, unless it is seen moving. Something that moved in that event (someone walking) is never remembered, and with only one AI look in the event nothing is (too little to tell what stood still). <b>Not a real alert</b> alone only marks the event. Taking the mark back forgets it. Switching to another AI model (or AI server) starts the remembered spots and these marks over on every camera: they are where that model drew its boxes.</p>' +
    '<p><b>Camera\'s own detection needs AI to agree</b> (off unless you turn it on): when the camera itself reports a person, vehicle or animal, it alerts only if AI sees one too; AI keeps looking while the camera reports. If AI cannot look, the camera\'s word counts. Doorbell presses, sounds and packages always count. The AI review says \u201cthe camera itself reported ..., but AI did not see one\u201d.</p>'],
  ['camera-tamper', 'Camera settings', 'Camera: Tamper', 'tamper covered blocked blacked out spray paint blurred out of focus moved knocked turned reference picture day night infrared sabotage',
    '<p>Alerts when the camera is <b>covered</b> (a cloth, tape, paint, a hand), <b>blurred</b> (smeared or sprayed lens, out of focus) or <b>moved</b> (knocked or turned, so the scene no longer matches). Off by default.</p>' +
    '<p>AmberSight keeps a <b>reference picture</b> for the day (color) and one for the night (gray, infrared), because cameras switch to black and white after dark. It takes each one by itself when the view has been still for a while and refreshes it slowly (about every 6 hours), so daylight, seasons and a new plant do not matter. <b>Set reference now</b> replaces the reference for the light the camera shows right now; use it after you have moved the camera on purpose, or when an alert is about a change that is here to stay.</p>' +
    '<p>Every few seconds the camera\'s picture is compared with the reference of the same light. Brightness changes (headlights, sunrise, a cloud, the infrared switch) are ignored; only what the picture shows counts. The wrong view must last the number of seconds you set (60 by default) before you are told, so a person walking close to the camera, a spider or rain do not set it off. You get one alert with the reference and the current picture, and "Camera view restored" once it looks right again for 30 seconds. <b>Sensitivity</b> 1 reports only plain cases, 5 also small changes.</p>' +
    '<p>The alert follows the camera\'s Alerts settings (services, priority, pause) and the profile; it is not sent while the system is disarmed. Home Assistant gets a Tamper sensor for the camera. Recent alerts are listed here: click one to see the two pictures. Until the reference for the current light exists (for night, the first quiet night), nothing is judged for that light. A very dark scene with no detail cannot be judged.</p>'],
  ['camera-unusual', 'Camera settings', 'Camera: Unusual activity', 'unusual out of pattern rare normal baseline learning hour of the week person night 3 am',
    '<p>AmberSight learns how often each label (person, car, ... or plain motion) normally happens at this camera in each hour of the week, from the events it has recorded (kept for up to 90 days, longer than the events themselves). An event at an hour when that label almost never happens is flagged: it gets the label <b>unusual</b> (use the Unusual chip in Events to list them) and its notification reads "Unusual: person at Back Gate at 3:12 AM". Off by default.</p>' +
    '<p>In the <b>alert</b> mode an unusual event always alerts at high priority, even on a camera that alerts only for strangers and even for a known person.</p>' +
    '<p>It needs history first: nothing is flagged until the camera has <b>Days of history needed</b> (14 by default) of events, and the page shows "Learning" until then. The pattern looks at the hour before and after too, and at the same hour on other days, so arriving a little early or on a different weekday is not unusual.</p>' +
    '<p><b>Labels it judges</b> picks what counts (the default is person). <b>Sensitivity</b>: 1 flags only what has never happened at that hour, 5 also hours that are only a little uncommon. <b>What it does</b>: only mark the event; a quiet notice (low priority); or a full alert (high priority). The grid shows what is normal here for a label, darker for more usual hours.</p>'],
  ['camera-av', 'Camera settings', 'Camera: Audio & text', 'audio sound overlay text burn timestamp',
    '<p><b>Audio</b>: sound in the live view and recordings, when the camera sends it. <b>Text on the picture</b>: your own text in a corner, with fill-ins {name}, {short}, {site}, {date}, {time}, and {v:NAME} for a value an automation pushes in (weather, a temperature from Home Assistant, and the like) over MQTT (<code>&lt;prefix&gt;/overlay/NAME/set</code>) or <code>POST /api/overlay/NAME</code>; a {v:NAME} value shows in live view, not in burned-in recordings. <b>Also burn it into recordings</b> (under More settings) makes the text part of the video files; that re-encodes the video, uses much more CPU, and turns off smooth live view for that camera (Live and the apps fall back to a snapshot that refreshes, with no sound; recordings are unaffected), so leave it off unless recordings must carry it.</p>'],
  ['settings-groups', 'Settings', 'Groups', 'group organize filter',
    '<p>Groups organize cameras for the Live view and can be used by other settings (Also trigger, layouts). A camera can be in several. Making a group never turns on recording or triggering by itself.</p>'],
  ['settings-motion', 'Settings', 'Motion sensitivity', 'algorithm objects frame-diff min object contrast travel min frames pre-roll post-roll arm window',
    '<p>The motion settings every camera uses unless it sets its own. Choose <b>Low</b>, <b>Medium</b> (the default) or <b>High</b>: High notices smaller and fainter movement, Low ignores more. <b>More settings</b> shows what each choice sets: <b>Smart</b> (recommended) follows moving things and ignores small or jittery changes, <b>Simple</b> fires on the share of the picture that changed; <b>Frames in a row</b> is how long motion must last before an event starts; <b>Keep before motion</b> and <b>Keep after motion</b> are the seconds kept around each event. <b>Only watch during a time window</b>: hours when detection runs (off = all day).</p>'],
  ['settings-storage', 'Settings', 'Storage & retention', 'segment retention days max storage cap automatic free space full',
    '<p><b>Segment length</b>: recordings are written in files of this many seconds. <b>Retention</b>: recordings older than this are deleted. <b>Space for recordings</b>: Automatic (the default) uses what the drive can spare and keeps 10% of it free (the percentage can be changed); Fixed size caps the data folder. Being full is normal: the oldest recordings make room. Folders, drives and the archive are set in Settings &rsaquo; Recording &rsaquo; Drives &amp; folders.</p>'],
  ['settings-alerts', 'Settings', 'Alerts', 'ntfy pushover telegram webhook home assistant system problems offline disk full test interval priority link browser phone push unifiedpush app push servers',
    '<p>Set each service up once; cameras use all of them unless their own Alerts tab picks some. Pictures go to <b>ntfy</b>, <b>Pushover</b> and <b>Telegram</b>; a <b>webhook</b> gets JSON; Home Assistant and a command can run too. The two limits hold back alerts that come too often (per camera, and across all cameras); held-back ones are still recorded. Set <b>this server\'s address</b> to one your phone can reach so tapping a notification opens the camera at that moment.</p>' +
    '<p><b>System problems</b>: a camera offline, recordings not being written, a drive nearly full or unreadable. Reported once it has lasted the minutes set, and again when resolved. <b>Send a test</b> checks the services.</p>' +
    '<p><b>Browser and phone push</b>: browsers turn notifications on themselves. Phone apps that use UnifiedPush deliver through a push server, usually ntfy; <b>Push servers for phone apps</b> lists the ones they may use. ntfy.sh is the public ntfy server; add your own ntfy server\'s host (host or host:port) to use it. Plain http:// works only for a server on the home network or Tailscale.</p>'],
  ['settings-odt', 'Settings', 'External detector', 'external detector command',
    '<p>Runs your own detector program on each event picture ({image} is its file) and adds the objects it prints to the event. Most people use the built-in AI instead (Settings &rsaquo; Detection &amp; alerts &rsaquo; Objects (AI)).</p>'],
  ['settings-servers', 'Settings', 'Servers (linking)', 'link another server code fingerprint share cameras tailscale',
    '<p>Link another AmberSight server (another site, a cabin) to switch between them signed in as the same user. On one server make a code (<b>Let another server link to this one</b>); on the other enter its address and the code, and check the certificate fingerprint matches. Per link you choose whether to share this server\'s cameras and whether to show theirs here. Only link servers you control: an admin there can sign in here as any user with the same name.</p>'],
  ['settings-share', 'Settings', 'Share streams', 'share restream rtsp home assistant scrypted vlc frigate nvr stream address url snapshot mjpeg generic camera port 8554 sub stream tcp',
    '<p><b>Share streams</b> lets other apps (Home Assistant, Scrypted, VLC, another NVR) use AmberSight as their camera source: they connect to AmberSight over RTSP instead of to each camera, so each camera still serves only AmberSight. The video is passed on exactly as the camera sends it (H.264 or H.265, no re-encoding, so it costs almost nothing), and a new viewer starts at once. Sound is shared when the camera sends AAC; G.711 sound is not (video only).</p>' +
    '<p>Turn on <b>Share camera streams</b> (off by default), choose the port (default 8554), then switch on each camera to share. Each shared camera shows its addresses with Copy buttons: <code>rtsp://USER:PASSWORD@host:8554/camera_name</code> is the main stream, adding <code>/sub</code> the sub stream (cameras that have one). Apps sign in with an AmberSight account (HTTP Basic, which is not encrypted: keep it on your own network or Tailscale); an account limited to some cameras only sees those, and anything not shared or not allowed looks like it does not exist. A password with special characters must be percent-encoded in the address (@ is %40).</p>' +
    '<p>Only TCP is offered, which Home Assistant, Scrypted, VLC and ffmpeg use or fall back to. A camera with a privacy mask or text overlay is shared only after you turn on <b>I understand: share it without the mask</b> for it, because the shared video shows the picture without the mask or overlay. Adding a mask to a shared camera stops its sharing until you confirm. For Home Assistant\'s Generic Camera also use the <b>Snapshot</b> address as the still image (with the same account in the authentication fields), or the <b>MJPEG</b> address. If a camera is switched off or offline, its shared stream is simply not there until it is back.</p>'],
  ['settings-https', 'Settings', 'HTTPS', 'https tls ssl certificate encrypted secure restart tailscale name own certificate trust http redirect',
    '<p><b>Use HTTPS</b> encrypts the connection. AmberSight makes its own certificate; nothing is published anywhere. Each device trusts it once (account menu, <b>Trust this server</b>); until then the browser warns that the connection is not private. Browsers only allow notifications, the microphone and keep screen awake on a trusted HTTPS page. Plain http:// addresses on the same port then redirect to https://.</p>' +
    '<p>Turning HTTPS on or off, or changing the certificate files, applies after a restart: <b>Restart now</b> restarts AmberSight (when it runs as a service) and then opens the new address; you sign in again there. Otherwise restart the service by hand. It is refused while an update is being installed. Notifications on a device belong to the address it turned them on at: turn them on again at the new address (account menu, Notifications on this device).</p>' +
    '<p><b>Extra names for the certificate</b>: the certificate already covers this computer\'s addresses, its name and localhost; add any other name you open AmberSight by. Names apply without a restart. The certificate authority is limited (so a stolen key could not be used against other sites): names ending in .lan, .local, .home.arpa or .internal, this computer\'s name, and home-network and Tailscale (100.x) addresses can always be added. Other names, such as a Tailscale name (nvr.tail1234.ts.net), are only covered by a certificate authority made with them: add them before HTTPS is first turned on, or use your own certificate.</p>' +
    '<p><b>Use my own certificate</b> (Advanced): the PEM files of a certificate you got elsewhere, full chain and private key, as paths on this server (at most 1 MB each). A renewed certificate is loaded at the next restart. Linked servers and paired capture helpers trust only AmberSight\'s own certificate authority, so they stop working with your own certificate and cannot be linked or paired again until you switch back. If the files cannot be read when AmberSight starts, it uses its own certificate instead and says so here.</p>' +
    '<p>Turning HTTPS off: phone apps and bookmarks that use the https:// address must use the http:// address instead; capture helpers, linked servers and the server switcher stop until HTTPS is on again (turning it back on restores them); alert links that use the https:// address must be changed (Settings &rsaquo; Detection &amp; alerts &rsaquo; Alerts); notifications and the microphone stop working. This browser is signed out before the restart, so it can sign in on the http:// address.</p>'],

  // ---------------------------------------------------------------- admin
  ['admin-status', 'Other settings', 'Status & updates', 'health online offline reconnects bitrate per day days kept fits storage forecast warnings problems',
    '<p>How the server is doing. The banner at the top says everything is OK only when every card below it is OK; otherwise it lists each thing to check in a few words, with the button that helps. <b>Storage</b> counts the archive folder too: the days kept are those of a folder together with the archive it moves old recordings to. A battery camera that is asleep is counted as asleep, not as offline. Per camera: bitrate, how much it records per day and how far back its recordings go. Per folder: how many days it holds at the measured rate. Below that, recent warnings and errors. To see which cameras use the most space, look at their per-day figures; switching a camera to "sub stream, main stream around events" usually cuts its share sharply. The <b>Updates</b> row under the cards shows new versions of AmberSight and installs them (see Updates).</p>'],
  ['updates', 'Other settings', 'Updates', 'update upgrade new version release download install previous rollback github apt dnf',
    '<p>The <b>Updates</b> row in Settings &rsaquo; System &rsaquo; Status shows this version and whether a newer one is out. <b>Check for updates</b> looks now; it also looks every 12 hours (<code>[update] check = false</code> in the config stops that). Nothing is installed until an admin clicks <b>Update</b>: AmberSight then downloads the package for this computer, checks it is signed by the AmberSight release key (an unsigned or changed package is refused), keeps the current program in the <b>previous</b> folder next to it, and restarts when it runs as a service (otherwise restart it yourself). To go back, stop AmberSight and copy the files from <b>previous</b> over the program. Installed with apt or dnf (a .deb or .rpm package)? Update with apt or dnf instead. From a terminal: <code>ambersight update --config config.toml</code> (<code>--check</code> only looks).</p>'],
  ['admin-profiles', 'Other settings', 'Profiles & schedule', 'home away night profile rules sunrise sunset schedule',
    '<p>A profile (e.g. Home, Away, Night) changes chosen camera settings: motion, alerts, AI, recording, motion only. Rules switch profiles by time of day, sunrise or sunset; the first rule covering the moment wins, otherwise the default profile applies. You can also pick a profile by hand for a while from the side panel.</p>'],
  ['admin-presence', 'Other settings', 'Presence', 'presence geofence geofencing phone home away leave arrive arm disarm everyone left',
    '<p>Phone apps signed in to this server can report whether the phone is at home. When every phone that reported recently is away for the chosen number of minutes, the server arms (or switches to the away profile); when one comes back it switches to the home profile, or back to the schedule, and disarms if you ticked that. Only these changes act: arming or switching by hand stays until the next one. A home profile stays until changed by hand or the next time everyone leaves; leaving replaces a profile chosen by hand. A phone that has not reported within the set hours is not counted; with no phone counting nothing happens then, and the server remembers who was last home or away (also across restarts), so coming back after a long trip still acts. You can pick which accounts\' phones count (none ticked: all); other accounts cannot report. Any counted phone coming back triggers the home actions. Each account reports its own phones; admins see and remove all of them here. For app makers, see the API guide (Presence).</p>'],
  ['admin-ai', 'Other settings', 'Objects (AI)', 'model yolox download labels confidence parked codeproject ai server',
    '<p>Download a detection model (it runs on this server; pictures never leave it): Tiny is the lightest, Small (recommended) suits most, and Large is the most accurate but takes about five times the work per check, so it needs a graphics card to keep up with several cameras. The page shows the measured time per check for the model in use. Or use an AI server you already run. Choose the objects that confirm an event, the minimum confidence (lower finds more, and more false alarms) and whether parked objects are ignored. Cameras can turn AI off or use their own objects.</p>'],
  ['admin-storage', 'Other settings', 'Drives & folders', 'folders drives archive cap full event footage disk guard network share days',
    '<p>Where recordings go. Cameras record into the <b>data folder</b> unless their setup picks another <b>folder</b> (another drive or a network share). Each folder can have a <b>cap</b>; when a folder is full, its oldest recordings move to the <b>archive</b> folder if there is one, otherwise they are deleted. A full folder that hands its oldest to the archive is working as intended, not a warning.</p>' +
    '<p><b>Also record the sub stream</b>: a small second copy of continuous cameras (about a tenth more space) for phones with Data saver on. <b>Keep event footage first</b>: when deleting, quiet footage goes before footage around events from the last N days (0 = off). Every drive also keeps 2% free (at least 1 GB) whatever the caps say. Protected events are never deleted.</p>' +
    '<p><b>Keep this folder private</b> (each extra folder): only administrators and AmberSight can open it, so browsing it in File Explorer or over a network share may stop working. It is applied in the background (a folder with many recordings can take several minutes; recording carries on) and the line under the switch shows whether it is private, open, being applied or could not be applied. It is on by default for a new or empty folder and off for one that already holds files; folders you added before are not changed until you switch them. A whole drive cannot be made private: choose a folder on it. Network drives and FAT or exFAT drives cannot be made private. Turning it off asks first, because the folder then gets what its parent allows, which may let other accounts open it again. Above the folders, the data folder (and on Windows the program folder) show their own state, read-only, with the reason when one was left alone.</p>'],
  ['admin-discovery', 'Other settings', 'Find cameras', 'find cameras onvif scan subnet add',
    '<p>Finds cameras on the network (ONVIF), tries the login you give (most people use one login for all their cameras; at most two tries each so cameras do not lock you out), and adds them with their main and sub streams. Cameras on another subnet need that address range filled in.</p>'],
  ['admin-users', 'Other settings', 'Users', 'accounts admin viewer cameras sign-in code password',
    '<p>Accounts and what they may do. An <b>admin</b> can change settings; others only view, optionally only some cameras (none ticked = all). A <b>sign-in code</b> lets a device sign in once without typing the password (one use, 10 minutes). There must always be at least one admin.</p>'],
  ['your-account', 'Other settings', 'Two-step codes and device tokens', 'two-step two factor 2fa mfa totp authenticator code recovery lost phone token app home assistant rtsp password security your account signed-in devices sign out other devices new device alert',
    '<p><b>Two-step codes</b> mean a stolen password alone does not get anyone in. Open the menu at the top, <b>Your account</b>, and turn them on: scan the picture with an authenticator app on your phone (Google Authenticator, Microsoft Authenticator, 1Password, Aegis and others), then type the code it shows. Save the 10 <b>recovery codes</b> somewhere that is not your phone: each one signs you in once if the phone is lost.</p>' +
    '<p>Nobody has to use them, but we recommend them for admin accounts.</p>' +
    '<p><b>Signed-in devices.</b> Your account lists every browser and phone that is signed in to it: its kind (such as Edge on Windows), the address it last came from, when it signed in and when it was last used. Sign out one you do not recognize with <b>Sign out</b>, or all but this one with <b>Sign out all other devices</b>. A device signed out here is signed out at once, and any video it had open ends. No password is asked for; if one is not yours, change your password too. Signing a device out also makes its browser new again, and takes off the notifications it turned on (ones turned on before this list existed cannot be matched: remove older devices in the account menu under Notifications on this device). Video open on your other devices stops for a moment and reconnects. Devices that signed in before this list existed show as <i>Signed in before this list existed</i> and keep working. Device tokens are listed separately below.</p>' +
    '<p><b>New device alerts.</b> When an account signs in from a browser it has not used before, admins get one message that names the account, the device, the address and how (password, two-step code, recovery code, QR code, a linked server, or a password sent directly by a program). Several in a minute are joined into one more message. Each browser is recognized by a small cookie, kept up to two years, that gives no access by itself (a program that signs in on every run should keep that cookie too, or use a device token, or admins are told every time). Nothing is sent for a first sign-in to a new account, or when the same browser already has a working session; after an update each browser is told once, the next time it signs in without one. A program that sends the password directly (HTTP Basic or RTSP) is told once per account and network, and its message says to change the password. <b>Changing a password</b> forgets every known browser except the one you changed it from, so each of your other browsers is told once at its next sign-in. Changing a password also signs the other devices out, and takes off the notifications they had turned on, so a device that is still signed in keeps getting alerts but one that was signed out does not until you sign in on it again (the page turns its notifications back on at sign-in). The phone of an admin that loses alerts this way, or by Sign out in Your account, is told, and the admins are told too. A second sign-in of the browser you are using is not forgotten. A plain <b>Sign out</b> keeps the browser known. These messages go out even when <b>Alert when something is wrong</b> is off.</p>' +
    '<p><b>Lost your phone?</b> Use a recovery code on the sign-in page. No codes left? Another admin can turn it off for you in Users (Edit). If you are the only admin, someone with access to the computer can run <code>ambersight user reset-two-step &lt;name&gt; --config &lt;file&gt;</code>, and if the password may be known, <code>ambersight user set-password &lt;name&gt; --config &lt;file&gt;</code>.</p>' +
    '<p><b>Someone keeps entering wrong codes?</b> Then they have your password. Admins get a warning. Change the password right away: a device that is still signed in can do it with your code, whatever is locked at the sign-in page. An address with too many wrong codes waits 10 minutes; other addresses are not affected, unless there are very many tries. A <b>recovery code</b> always works at the sign-in page, also during such a wait.</p>' +
    '<p><b>Your own password.</b> Always takes your current password, and your code when two-step codes are on. An admin who disabled the wrong account, or is locked out, can run <code>ambersight user enable &lt;name&gt; --config &lt;file&gt;</code> on the computer.</p>' +
    '<p><b>Device tokens</b> are for programs that watch or do everyday things and cannot ask for a code, such as Home Assistant or an RTSP player. Make one in Your account, give it a name, and copy it: it is shown only once. A <b>watch-only</b> token sees live video, events, clips and recordings. One with <b>day-to-day control</b> can also arm and disarm, change profile and pause notifications (for a day at most), move cameras, record a clip and review events; admins are told when it disarms or pauses. It cannot save presets or start tours. No token can change settings, passwords or accounts, get notifications, or report presence: an app that needs those signs in with a password or a QR code. Each works until you revoke it, also after you change your password. An admin who stops being an admin loses tokens with control for good.</p>' +
    '<p>RTSP is not encrypted, so it takes watch-only tokens only: your username with the token as the password. Use it on a network you trust.</p>' +
    '<p>A QR code for phone sign-in from the Users page still works for an account with two-step codes: the admin who made it vouches for that person. Making an admin, setting someone else\'s password, turning off someone\'s codes, a QR code for an admin or an account with two-step codes, enabling a disabled admin, commands that run programs (external detector, alert action), where backups go, linking servers, and where or whether alerts arrive all take the admin\'s own password (and code), so a stolen session alone cannot do them. That last one means the alert services, the address notifications open, system alerts and how soon they go out, the Pushover sound, taking a push server off the list, turning off or narrowing the morning summary, and turning on the watchdog or letting it wait or try longer (it holds back the offline alert while it works). A session that keeps getting that wrong is signed out and admins are told. Admins also hear when an admin adds or removes a device for notifications, and when a restart is asked for. New usernames are at most 64 characters, with nothing that does not show. Sign-in from a linked server does not: that person signs in here with their code.</p>'],
  ['events-follow', 'Watching', 'Follow: where did they go?', 'follow track same person vehicle other cameras path re-identification smart search',
    '<p>On an event with a person or vehicle, <b>Follow</b> looks for the same one on other cameras in the minutes before and after, and lists the sightings in time order: camera, time, picture, how well it matches. Tap a sighting to play that camera at that moment, or <b>Follow from here</b> to carry on from it.</p>' +
    '<p>It compares how the person or vehicle <i>looks</i> (shape, colors, clothes or paint) using the smart search model, and is raised when the same recognized face or the same plate was read in both events. This is approximate: someone dressed alike can match, and the same person seen from another angle, in other light or far away can score low. The slider hides weak matches (it starts at 80%); lower it to see more, and look at the pictures before trusting a match. Use the window and "this camera too" to widen the search. It needs smart search to be on, and works on events whose pictures have been searched (older events are done in the background, newest first).</p>'],
  ['admin-alertrules', 'Other settings', 'Alert rules', 'alert rules plain words quiet rule delivery truck smart search threshold test tag priority notice',
    '<p>Write what should alert you in words, such as "a delivery truck stopped out front" or "a person carrying a box on the porch", and choose the cameras, a time window and what happens: an alert (normal or high priority), a quiet notice, or only a tag on the event. Every new event\'s pictures are compared with the words; a match tags the event "rule: name" and sends the alert under the rule\'s name ("Delivery truck out front at Front Door"). It comes a few seconds after the ordinary alert, once the pictures are checked, and the same rule alerts again for a camera only after the number of minutes set.</p>' +
    '<p><b>Test against recent events</b> shows the recent events that look most like your words with their scores; green ones would have matched at the current threshold. Move the threshold between the events you want and the ones you do not, then save. The match is approximate: it can miss, and it can match something that only looks a bit like the words.</p>' +
    '<p>A <b>quiet rule</b> ("my own car in the driveway") tags matching events "quiet: name" and stops their alerts, the ordinary one and other rules\' alerts alike. To make that possible, ordinary alerts of the cameras a quiet rule covers wait up to the seconds set for the pictures to be checked; if they are not checked in time they go out as usual. Cameras without a quiet rule are never delayed. If a quiet rule drops an alert, the event\'s AI review says so. A rule\'s own alert is not sent for an event whose ordinary alert was kept quiet because the person was known (strangers only, or a person marked "no alerts"). Events are still recorded and listed. Rules work only while smart search is on, and look at events as they happen, not at old ones.</p>'],
  ['admin-faces', 'Other settings', 'Faces', 'face recognition people names known unknown doorbell import no alerts family',
    '<p>When AI sees a person, AmberSight looks for a face in the full-quality recording and compares it with the faces you have named; the event is labeled with the name, or "unknown face". It works best on doorbells and cameras that see people close and front-on; faces smaller than the size set are skipped. Turn it on here (it downloads two small models, about 39 MB, that run on this server).</p>' +
    '<p>Click a face under <b>Faces to name</b> to say who it is; ticking "also name faces that look like this one" names the look-alikes too. A few clear faces of each person (daylight and night) make it much more reliable. <b>Import named faces</b> reads a folder with one sub-folder per person. For each person you can turn on <b>No alerts when only they are seen</b>: such events are kept but send no alert. Faces nobody names are forgotten after 60 days, or with their event; <b>Forget</b> deletes a person and every picture of their face. Face pictures live in this server\'s database and backups, and names appear in alerts. A photo can fool face recognition, so do not rely on \'no alerts\' for security.</p>'],
  ['admin-lpr', 'Other settings', 'License plates', 'license plate number plate lpr anpr car vehicle known unknown driveway gate read',
    '<p>When AI sees a car, truck or motorcycle that is not parked, AmberSight finds its plate in the full-quality recording, reads it, and labels the event: "plate ABC123 (Mom\'s car)" for a plate you have named, "unknown plate ABC123" for any other. The alert says which car it was. Several frames are read and the surest reading is kept. Turn it on here (plates are found by a model built into AmberSight and read by a small free model, about 5 MB, that downloads once; both run on this server\'s processor), then switch on the cameras that see plates.</p>' +
    '<p>It works best on a camera that sees plates close, straight on and lit, such as a driveway or gate camera; a plate under about 50 pixels wide (in the recording) is skipped, and you can change that and how sure a reading must be, for every camera or one. <b>Whole picture</b> makes a camera look for plates in the whole frame when AI saw no vehicle (a camera aimed at a gate).</p>' +
    '<p><b>Known plates</b> are the cars you have named, with optional notes. A reading matches one when it is the same plate, or one character different, or differs only in look-alike characters (O and 0, I and 1, B and 8 ...); change that under <b>Matching</b>. Name a plate from <b>Seen lately</b> with Add to known, or from the event itself. Search the event list for a plate (or part of one) to find its events; the same readings go to Home Assistant over MQTT ("Last plate" and a "Plate" event, known or unknown).</p>' +
    '<p>Plate pictures and readings stay in the database; unknown plates are forgotten after 6 months, known ones stay. Do not rely on a plate alone for security: plates can be copied or misread.</p>'],
  ['settings-digest', 'Settings', 'Morning summary', 'morning summary digest daily overnight report recap unknown people vehicles packages offline tamper email',
    '<p>One message a day about what happened at your cameras since the last summary: people (known by name, unknown, or with no face seen), vehicles (known plates by name, unknown plates), packages delivered and picked up, loitering and line crossings, tamper alerts, unusual events and cameras that went offline. It is worked out on this server from its own events, with no cloud service. Counts are events, not individual people.</p>' +
    '<p>Choose the time (this server\'s local time), what it covers (overnight from the time the night starts, the last 24 hours, or since the last summary), the services and the cameras. Phones and browsers get a short message that opens the full summary page; each highlight there opens its event. ntfy and Telegram get a longer text, and email gets a version with pictures. Links in messages need the server\'s address under Notifications. <b>Skip it when nothing happened</b> sends nothing on a quiet day. <b>Preview</b> shows the next summary without sending; <b>Send a summary now</b> tests the services.</p>'],
  ['settings-strangers', 'Settings', 'Alert only for strangers', 'strangers unknown person unknown vehicle known face known plate night first time seen quiet',
    '<p>In a camera\'s Alerts settings, <b>Only alert for unknown people and vehicles</b> keeps the camera quiet for people whose face you named (Settings &rsaquo; Smart features &rsaquo; Faces) and for vehicles whose plate you named (License plates). The events are still recorded and labeled; the AI review says why no alert was sent. An unknown face, an unknown plate, or someone whose face could not be identified (turned away, too far; or a car whose plate was not read) alerts, with a message such as "Unknown person at Front Door" or "Unknown car ABC123 in Driveway". Turn off <b>Count people and vehicles that could not be identified as unknown</b> to keep those quiet instead.</p>' +
    '<p>With <b>Only during</b> hours (for example night) the filter applies inside them; outside, alerts are as usual, or none for people and vehicles. <b>Alert only the first time</b> stays quiet for an unknown person or plate that was already seen in the last days. For this the camera needs AI on, and faces and/or plates turned on; the alert waits a few seconds for the faces to be looked at (other cameras are not delayed).</p>'],
  ['admin-logs', 'Other settings', 'Logs', 'warnings errors log',
    '<p>The server\'s recent warnings and errors, newest first. Useful when a camera keeps reconnecting or a notification does not arrive.</p>'],
  ['admin-audit', 'Other settings', 'Audit log', 'who changed sign in history',
    '<p>Who signed in and who changed what, and when.</p>'],
  ['admin-aireview', 'Other settings', 'AI review', 'why no alert missing alerts false alarms almost nothing found frames fix',
    '<p>What AI saw in each motion event and why it did or did not alert. "Almost" means it saw something wanted but was not sure enough: worth a look if alerts are missing. Many "Nothing found" usually means shadows, lights or bugs: raise the camera\'s motion thresholds or add an ignore zone. Open an event for its frames and one-click fixes. "Same spot" means what AI saw has been in that spot in several earlier events, or you marked it not real there (see Camera: AI). A filter above the list (Camera only, Parked ...) looks through the whole period, not only the latest events.</p>'],
  ['home-assistant', 'Other settings', 'Home Assistant and MQTT', 'mqtt home assistant sensor motion problem automation',
    '<p>With an MQTT broker set, every camera appears in Home Assistant by itself (motion, objects, snapshot, online), plus a server "Problem" sensor that turns on with any system problem. Alerts can also call a Home Assistant service directly (Settings &rsaquo; Detection &amp; alerts &rsaquo; Alerts).</p>'],
];

const byId = new Map(TOPICS.map(t => [t[0], t]));
const topicHtml = (t) => '<div class="helptopic" data-topic="' + t[0] + '"><h4>' + esc(t[2]) + '</h4>' + t[4] + '</div>';
const plain = (html) => html.replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/g, ' ');

// Topic for a "?" button, from the selected tab next to it.
function topicFor(btn) {
  if (btn.dataset.topic && byId.has(btn.dataset.topic)) return btn.dataset.topic;
  const prefix = btn.dataset.help;
  const bar = btn.parentElement;
  const on = bar && bar.querySelector('[data-p].on');
  const id = on ? prefix + '-' + on.dataset.p : prefix;
  return byId.has(id) ? id : (byId.has(prefix) ? prefix : 'start');
}

export function helpButton(prefix) {
  return '<a href="#" class="helpq" data-help="' + esc(prefix) + '" title="Help for this page" aria-label="Help for this page">?</a>';
}

export function openHelp(id) {
  const t = byId.get(id) || byId.get('start');
  const d = openDlg(t[2], t[4] + '<div class="row"><a href="#help" data-all>All help topics</a></div>', true);
  d.classList.add('helpdlg');
  d.querySelector('[data-all]').onclick = (e) => {
    e.preventDefault();
    d.__close();
    pendingTopic = t[0];
    import('./nav.js').then(m => { m.showTab('help'); showPending(); });
  };
}

let pendingTopic = null;
let tabEl = null;

// "How do I...": [title, one line, topic id].
const HOWTO = [
  ['Add a camera', 'Type its address, or let AmberSight find it', 'settings-cameras'],
  ['Get alerts on my phone', 'Notifications with a picture', 'settings-alerts'],
  ['Save or share a clip', 'Download an event or a snapshot', 'share-clip'],
  ['Watch away from home', 'Safe remote viewing', 'away-from-home'],
  ['Arm and disarm', 'Turn motion detection on or off', 'arming'],
  ['See what happened today', 'Events, newest first', 'events'],
  ['Add another person', 'Their own sign-in', 'admin-users'],
  ['Protect my sign-in', 'Two-step codes and tokens for apps', 'your-account'],
  ['Keep recordings longer', 'Days kept and drive space', 'settings-storage'],
];
const slug = (t) => t.toLowerCase().replace(/[^a-z0-9]+/g, '-');

// Open a topic's section, scroll to it and flash it.
function jumpTo(id) {
  const el = tabEl && tabEl.querySelector('[data-topic="' + id + '"]');
  if (!el) return;
  const d = el.closest('details');
  if (d) d.open = true;
  el.scrollIntoView({ block: 'start', behavior: 'smooth' });
  el.classList.add('flash');
  setTimeout(() => el.classList.remove('flash'), 1600);
}

function showPending() {
  if (!tabEl || !pendingTopic) return;
  const q = tabEl.querySelector('[data-hq]');
  if (q && q.value) { q.value = ''; filter(''); }
  const id = pendingTopic;
  pendingTopic = null;
  jumpTo(id);
}

function filter(q) {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  const searching = words.length > 0;
  let shown = 0;
  tabEl.querySelectorAll('.helptopic').forEach(el => {
    const t = byId.get(el.dataset.topic);
    const hay = t._hay || (t._hay = (t[1] + ' ' + t[2] + ' ' + t[3] + ' ' + plain(t[4])).toLowerCase());
    const ok = words.every(w => hay.includes(w));
    el.hidden = !ok;
    if (ok) shown++;
  });
  // Topics whose title has every word come first (in their section, and their sections first);
  // with no search, the usual order.
  const titled = (el) => searching && words.every(w => byId.get(el.dataset.topic)[2].toLowerCase().includes(w)) ? 0 : 1;
  const rank = (el, i) => [titled(el), i];
  const byRank = (a, b) => a.r[0] - b.r[0] || a.r[1] - b.r[1];
  const secs = [...tabEl.querySelectorAll('[data-hsec]')].map((sec, si) => {
    const tops = [...sec.querySelectorAll('.helptopic')];
    tops.forEach((el, i) => { if (el.dataset.ord == null) el.dataset.ord = i; });
    const sorted = tops.map(el => ({ el, r: rank(el, +el.dataset.ord) })).sort(byRank);
    sorted.forEach(x => sec.appendChild(x.el));
    if (sec.dataset.ord == null) sec.dataset.ord = si;
    const any = !!sec.querySelector('.helptopic:not([hidden])');
    sec.hidden = !any;
    if (searching) sec.open = any;
    return { el: sec, r: [any && sorted.some(x => !x.el.hidden && x.r[0] === 0) ? 0 : 1, +sec.dataset.ord] };
  });
  const parent = secs.length && secs[0].el.parentNode;
  if (parent) secs.sort(byRank).forEach(x => parent.appendChild(x.el));
  tabEl.querySelector('[data-hcards]').hidden = searching;
  tabEl.querySelector('[data-htoc]').hidden = searching;
  tabEl.querySelector('[data-hnone]').hidden = shown > 0;
}

function render(el) {
  const sections = [...new Set(TOPICS.map(t => t[1]))];
  el.innerHTML = '<div class="helpwrap"><div class="helpsearch"><input type="search" data-hq placeholder="Search help" aria-label="Search help"></div>' +
    '<div class="hwcards" data-hcards><h3 class="hwh">How do I...</h3><div class="hwgrid">' +
    HOWTO.map(h => '<button type="button" class="hwcard" data-go="' + h[2] + '"><b>' + esc(h[0]) + '</b><small>' + esc(h[1]) + '</small></button>').join('') + '</div></div>' +
    '<nav class="hwtoc" data-htoc aria-label="Contents"><span>Sections</span>' + sections.map(s => '<a href="#help" data-sec="' + slug(s) + '">' + esc(s) + '</a>').join('') + '</nav>' +
    '<p class="empty" data-hnone hidden>Nothing matches. Try fewer or other words.</p>' +
    sections.map(s => '<details class="hsec" data-hsec="' + slug(s) + '"><summary class="helpsec"><h3>' + esc(s) + '</h3></summary>' + TOPICS.filter(t => t[1] === s).map(topicHtml).join('') + '</details>').join('') + '</div>';
  const q = el.querySelector('[data-hq]');
  q.oninput = () => filter(q.value);
  el.querySelector('[data-hcards]').onclick = (e) => { const b = e.target.closest('[data-go]'); if (b) jumpTo(b.dataset.go); };
  el.querySelector('[data-htoc]').onclick = (e) => {
    const a = e.target.closest('[data-sec]');
    if (!a) return;
    e.preventDefault();
    const d = el.querySelector('[data-hsec="' + a.dataset.sec + '"]');
    d.open = true;
    d.scrollIntoView({ block: 'start', behavior: 'smooth' });
  };
}

// Any "?" anywhere opens its topic.
document.addEventListener('click', (e) => {
  const b = e.target.closest && e.target.closest('.helpq');
  if (!b) return;
  e.preventDefault();
  e.stopPropagation();
  openHelp(topicFor(b));
}, true);

export const helpTab = {
  id: 'help', label: 'Help', order: 90,
  init(el) { tabEl = el; render(el); },
  show() { showPending(); const q = tabEl && tabEl.querySelector('[data-hq]'); if (q && !pendingTopic && window.innerWidth > 800) q.focus(); },
};
